const STORE_KEY='eventgenie-demo-v1';
const DEMO_CHAT_KEY='eventgenie-demo-chat-v1';
const initial={event:{name:'An evening to remember',type:'Wedding',date:'2026-12-12',time:'',location:'Jaipur, Rajasthan',guests:120,budget:1200000,currency:'₹',theme:'Garden romance',venue:'Outdoor garden',venueTier:'',dietary:'Vegetarian options',cateringNotes:'',priorities:'Beautiful photography, guest comfort'},expenses:[{id:1,name:'Garden venue',category:'Venue',planned:300000,actual:0},{id:2,name:'Catering',category:'Catering',planned:300000,actual:0},{id:3,name:'Florals & decor',category:'Decoration',planned:180000,actual:0},{id:4,name:'Photography',category:'Photography',planned:120000,actual:0},{id:5,name:'Music & entertainment',category:'Entertainment',planned:90000,actual:0},{id:6,name:'Invitations',category:'Invitations',planned:45000,actual:0},{id:7,name:'Attire & beauty',category:'Clothing',planned:90000,actual:0},{id:8,name:'Contingency',category:'Miscellaneous',planned:75000,actual:0}],tasks:[{id:1,title:'Shortlist and visit venues',category:'Venue',due:'2026-11-05',priority:'High',status:'Completed'},{id:2,title:'Confirm guest list and save the dates',category:'Guests',due:'2026-11-10',priority:'High',status:'In progress'},{id:3,title:'Book photographer',category:'Vendor',due:'2026-11-14',priority:'High',status:'Not started'},{id:4,title:'Choose menu and arrange tasting',category:'Catering',due:'2026-11-20',priority:'Medium',status:'Not started'},{id:5,title:'Finalize flowers and table styling',category:'Decoration',due:'2026-11-26',priority:'Medium',status:'Not started'},{id:6,title:'Send formal invitations',category:'Guests',due:'2026-11-28',priority:'High',status:'Not started'}],vendors:[{id:1,name:'The Marigold House',category:'Venue',contact:'hello@marigold.example',location:'Jaipur',quote:300000,status:'Shortlisted',notes:'Garden venue; capacity to confirm'},{id:2,name:'Saffron Table Co.',category:'Catering',contact:'+91 98765 43210',location:'Jaipur',quote:240000,status:'Contacted',notes:'Vegetarian menu options'},{id:3,name:'Golden Hour Studio',category:'Photography',contact:'studio@example.test',location:'Jaipur',quote:120000,status:'Shortlisted',notes:'Portfolio link pending'}],guests:[{id:1,name:'Aarav Mehta',contact:'aarav@example.test',category:'Family',rsvp:'Yes',dietary:'Vegetarian'},{id:2,name:'Mira Kapoor',contact:'mira@example.test',category:'Friends',rsvp:'Pending',dietary:'None'},{id:3,name:'Kabir Shah',contact:'kabir@example.test',category:'Family',rsvp:'Yes',dietary:'Jain'}],ideasSaved:[],chat:[{who:'ai',text:'Hello Priya! I’m Genie, your event planning companion. I can help you think through your saved event, budget, and next steps. What would you like to work on?'}]};
let state;try{state=JSON.parse(localStorage.getItem(STORE_KEY))||structuredClone(initial)}catch{state=structuredClone(initial)}
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];let view='home',toastTimer,apiUser=null,cloudMode=false,authRequired=false,authTab='login',authPage='landing',saveTimer,cloudRevision=0,cloudSaveQueue=Promise.resolve(),chatHistory=[],chatBusy=false,lastFailedMessage='',optimisticMessage='',chatConfig={configured:false,model:null};
const money=n=>`${state.event.currency||'₹'}${Number(n||0).toLocaleString('en-IN')}`,dateFmt=d=>d?new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not set',save=()=>{if(!cloudMode)localStorage.setItem(STORE_KEY,JSON.stringify(state));if(cloudMode){clearTimeout(saveTimer);saveTimer=setTimeout(persistCloud,450)}},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function totals(){return{planned:state.expenses.reduce((a,x)=>a+ +x.planned,0),actual:state.expenses.reduce((a,x)=>a+ +x.actual,0),allocated:state.expenses.reduce((a,x)=>a+ +x.planned,0),done:state.tasks.filter(x=>x.status==='Completed').length}}
function setView(v){view=v;$('#sidebar').classList.remove('open');$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('#crumb').textContent=({home:'Overview',budget:'Budget',timeline:'Timeline',vendors:'Vendors',guests:'Guests',ideas:'AI ideas',assistant:'AI assistant',reports:'Reports'}[v]||'Overview');render()}
function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${view==='home'?'SATURDAY, OCTOBER 31, 2026':'YOUR EVENT WORKSPACE'}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function button(label,act,kind='primary-button',icon=''){return `<button class="${kind}" data-action="${act}">${icon?`<span class="button-icon">${icon}</span>`:''}${label}</button>`}
function renderHome(){let e=state.event,t=totals(),days=Math.max(0,Math.ceil((new Date(e.date+'T00:00:00')-new Date('2026-10-31T00:00:00'))/86400000)),open=state.tasks.filter(x=>x.status!=='Completed').slice(0,4);return `${heading('A little magic goes a long way ✨',`Here’s your planning snapshot for ${esc(e.name)}.`,button('Edit event details','edit-event','primary-button','✎'))}<div class="metric-grid"><div class="metric-card"><div class="metric-top">Days to go <span class="metric-icon">◷</span></div><div class="metric-value">${days}</div><div class="metric-note">Until your special day</div></div><div class="metric-card"><div class="metric-top">Guests invited <span class="metric-icon">♧</span></div><div class="metric-value">${state.guests.length} <small style="font:10px 'DM Sans';color:#999">/ ${e.guests}</small></div><div class="metric-note">${state.guests.filter(x=>x.rsvp==='Yes').length} confirmed so far</div></div><div class="metric-card"><div class="metric-top">Budget planned <span class="metric-icon">◉</span></div><div class="metric-value">${money(t.planned)}</div><div class="metric-note">of ${money(e.budget)} total budget</div></div><div class="metric-card"><div class="metric-top">Tasks completed <span class="metric-icon">✓</span></div><div class="metric-value">${t.done} <small style="font:10px 'DM Sans';color:#999">/ ${state.tasks.length}</small></div><div class="metric-note">You’re making lovely progress</div></div></div><div class="dashboard-grid"><div><div class="card"><div class="card-header"><div><div class="card-title">Your upcoming celebration</div><div class="card-subtitle">The details that make it yours</div></div><button class="link-button" data-action="edit-event">Edit event →</button></div><div class="event-feature"><div class="event-art"><div class="event-art-label">Made with love · 2026</div></div><div class="event-info"><span class="event-tag">${esc(e.type)}</span><h2>${esc(e.name)}</h2><div class="event-meta"><span>▦ ${dateFmt(e.date)}</span><span>⌖ ${esc(e.location)}</span><span>♧ ${e.guests} guests</span></div><div class="event-footer"><div class="countdown"><strong>${days}</strong><small>days to go</small></div><div class="progress-wrap"><div class="progress-label"><span>Planning progress</span><span>${state.tasks.length?Math.round(t.done/state.tasks.length*100):0}%</span></div><div class="progress-track"><span style="width:${state.tasks.length?Math.round(t.done/state.tasks.length*100):0}%"></span></div></div></div></div></div></div><div class="card section-gap"><div class="card-header"><div><div class="card-title">Your next steps</div><div class="card-subtitle">Small steps make big days</div></div><button class="link-button" data-view="timeline">All tasks →</button></div><div class="tasks-list">${open.length?open.map(taskRow).join(''):'<div class="overview-meta">Everything on your list is complete ✨</div>'}</div></div></div><div class="side-stack"><div class="card"><div class="card-header"><div><div class="card-title">Budget at a glance</div><div class="card-subtitle">A thoughtful plan for every rupee</div></div><button class="link-button" data-view="budget">Details →</button></div><div class="budget-summary"><div class="donut"><div class="donut-center"><strong>${Math.min(100,Math.round(t.planned/(e.budget||1)*100))}%</strong><small>allocated</small></div></div><div class="budget-amounts"><div><small>Planned</small><strong>${money(t.planned)}</strong></div><div><small>Still available</small><strong>${money(e.budget-t.planned)}</strong></div></div></div><div class="legend">${state.expenses.slice(0,4).map((x,i)=>`<div class="legend-item"><span class="legend-dot" style="background:${['#6b57c8','#eab279','#8296bd','#8ab7a8'][i%4]}"></span>${esc(x.category)}<b>${money(x.planned)}</b></div>`).join('')}</div></div><div class="card"><div class="card-header"><div><div class="card-title">Your vendors</div><div class="card-subtitle">The dream team taking shape</div></div><button class="link-button" data-view="vendors">See all →</button></div>${state.vendors.slice(0,3).map(v=>`<div class="vendor-row"><div class="vendor-logo">${esc(v.name.slice(0,1))}</div><div class="vendor-copy"><strong>${esc(v.name)}</strong><small>${esc(v.category)} · ${money(v.quote)}</small></div><span class="status-pill ${v.status==='Contacted'?'pending':''}">${esc(v.status)}</span></div>`).join('')}</div></div></div>`}
function taskRow(x){return `<div class="task-row ${x.status==='Completed'?'is-done':''}"><button class="task-check ${x.status==='Completed'?'checked':''}" data-toggle-task="${x.id}" aria-label="Mark ${esc(x.title)} complete">${x.status==='Completed'?'✓':''}</button><div class="task-copy"><strong>${esc(x.title)}</strong><small>${esc(x.category)} · ${esc(x.priority)} priority</small></div><span class="task-date">${dateFmt(x.due)}</span></div>`}
function renderBudget(){let t=totals(),colors=['#6b57c8','#eab279','#8296bd','#8ab7a8','#d59b93','#c2ae78'];return `${heading('Budget, beautifully balanced',`Your ${money(state.event.budget)} budget at a glance. Every number is calculated from your saved plan.`,button('＋ Add expense','add-expense'))}<div class="metric-grid"><div class="metric-card"><div class="metric-top">Total event budget <span class="metric-icon">◉</span></div><div class="metric-value">${money(state.event.budget)}</div><div class="metric-note">Your approved event limit</div></div><div class="metric-card"><div class="metric-top">Planned expenses <span class="metric-icon">▤</span></div><div class="metric-value">${money(t.planned)}</div><div class="metric-note">${t.planned>state.event.budget?'Over budget by '+money(t.planned-state.event.budget):money(state.event.budget-t.planned)+' unallocated'}</div></div><div class="metric-card"><div class="metric-top">Actual expenses <span class="metric-icon">✓</span></div><div class="metric-value">${money(t.actual)}</div><div class="metric-note">Payments recorded to date</div></div><div class="metric-card"><div class="metric-top">Remaining budget <span class="metric-icon">✧</span></div><div class="metric-value">${money(state.event.budget-t.actual)}</div><div class="metric-note">Budget less actual spend</div></div></div><div class="page-columns"><div class="card"><div class="card-header"><div><div class="card-title">Expense breakdown</div><div class="card-subtitle">Estimates can be updated with vendor quotations</div></div><button class="link-button" data-action="optimizer">Adjust budget →</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Expense</th><th>Category</th><th>Planned</th><th>Actual</th><th></th></tr></thead><tbody>${state.expenses.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.category)}</td><td>${money(x.planned)}</td><td>${money(x.actual)}</td><td><div class="table-actions"><button class="small-action" data-edit-expense="${x.id}">Edit</button><button class="small-action" data-delete-expense="${x.id}">×</button></div></td></tr>`).join('')||'<tr><td colspan="5">No expenses yet. Add your first line item.</td></tr>'}</tbody></table></div><div class="budget-total"><span>Planned expenses</span><strong>${money(t.planned)}</strong></div><div class="budget-total"><span>Budget available to allocate</span><strong>${money(state.event.budget-t.planned)}</strong></div>${t.planned>state.event.budget?'<div class="alert-note">Your estimates exceed the event budget. Use “Adjust budget” to rebalance the planned categories.</div>':''}</div><div class="card"><div class="card-header"><div><div class="card-title">Planned by category</div><div class="card-subtitle">A live view of your allocations</div></div></div>${state.expenses.map((x,i)=>`<div class="category-bar"><div class="category-bar-label">${esc(x.category)}</div><div class="bar-track"><span style="width:${Math.min(100,x.planned/(state.event.budget||1)*100)}%;background:${colors[i%colors.length]}"></span></div><div class="category-value">${money(x.planned)}</div></div>`).join('')}<div class="alert-note">Costs shown are planning estimates unless you entered a vendor quotation. No external prices are verified.</div></div></div>`}
function renderTimeline(){let sorted=[...state.tasks].sort((a,b)=>a.due.localeCompare(b.due)),done=totals().done,soon=sorted.filter(x=>x.status!=='Completed'&&x.due<state.event.date);return `${heading('A timeline you can actually follow','Your tasks, in date order, with the next steps close at hand.',button('＋ Add task','add-task'))}<div class="metric-grid"><div class="metric-card"><div class="metric-top">All tasks <span class="metric-icon">☷</span></div><div class="metric-value">${state.tasks.length}</div><div class="metric-note">Across your event plan</div></div><div class="metric-card"><div class="metric-top">Completed <span class="metric-icon">✓</span></div><div class="metric-value">${done}</div><div class="metric-note">${state.tasks.length?Math.round(done/state.tasks.length*100):0}% of your checklist</div></div><div class="metric-card"><div class="metric-top">Still to do <span class="metric-icon">◷</span></div><div class="metric-value">${state.tasks.length-done}</div><div class="metric-note">You’ve got this</div></div><div class="metric-card"><div class="metric-top">Needs attention <span class="metric-icon">!</span></div><div class="metric-value">${soon.length}</div><div class="metric-note">Open tasks due before event day</div></div></div><div class="page-columns"><div class="card"><div class="card-header"><div><div class="card-title">Your planning timeline</div><div class="card-subtitle">Check off tasks as you go</div></div></div><div class="tasks-list">${sorted.map(taskRow).join('')||'<div class="empty-state"><div class="empty-icon">◷</div><h3>A little room to plan</h3><p>Add tasks to create your event timeline.</p></div>'}</div></div><div class="card"><div class="card-header"><div><div class="card-title">Your event-day flow</div><div class="card-subtitle">A starter schedule to customize</div></div></div>${[['10:00','Venue setup & final checks'],['12:00','Vendor arrivals and sound check'],['14:00','Guest welcome'],['15:00','Ceremony / main moment'],['17:00','Dinner and celebrations'],['21:00','Farewell & tidy up']].map((x,i)=>`<div class="timeline-item"><div class="timeline-date">${x[0]}</div><div class="timeline-dot ${i<2?'done':''}"></div><div class="timeline-copy"><strong>${x[1]}</strong><small>${i<2?'Suggested schedule':'Editable event-day idea'}</small></div></div>`).join('')}</div></div>`}
function renderVendors(){return `${heading('Meet your dream team','Keep quotes and conversations together. Vendors here are manually entered, not verified.',button('＋ Add vendor','add-vendor'))}<div class="card"><div class="card-header"><div><div class="card-title">Vendor shortlist</div><div class="card-subtitle">Compare quotes and keep booking status up to date</div></div><input class="search-input" id="vendorSearch" placeholder="Search vendors…"></div><div class="table-wrap"><table class="table" id="vendorTable"><thead><tr><th>Business</th><th>Service</th><th>Contact</th><th>Quote</th><th>Status</th><th>Notes</th><th></th></tr></thead><tbody>${state.vendors.map(v=>`<tr><td><strong>${esc(v.name)}</strong><br><small>${esc(v.location||'')}</small></td><td>${esc(v.category)}</td><td>${esc(v.contact||'—')}</td><td>${money(v.quote)}</td><td><span class="status-pill ${v.status==='Booked'?'':'pending'}">${esc(v.status)}</span></td><td>${esc(v.notes||'—')}</td><td><button class="small-action" data-delete-vendor="${v.id}">Remove</button></td></tr>`).join('')||'<tr><td colspan="7">No vendors yet. Add a vendor or quote to get started.</td></tr>'}</tbody></table></div></div>`}
function renderGuests(){let yes=state.guests.filter(x=>x.rsvp==='Yes').length,pending=state.guests.filter(x=>x.rsvp==='Pending').length;return `${heading('Your people, all in one place','A private guest list for your event. Import and export CSV any time.',`<div class="toolbar"><label class="secondary-button" style="cursor:pointer">Import CSV<input id="guestImport" type="file" accept=".csv,text/csv" hidden></label>${button('Export CSV','export-guests','secondary-button')}${button('＋ Add guest','add-guest')}</div>`)}<div class="metric-grid"><div class="metric-card"><div class="metric-top">Guest records <span class="metric-icon">♧</span></div><div class="metric-value">${state.guests.length}</div><div class="metric-note">Planned capacity ${state.event.guests}</div></div><div class="metric-card"><div class="metric-top">Attending <span class="metric-icon">✓</span></div><div class="metric-value">${yes}</div><div class="metric-note">RSVP yes</div></div><div class="metric-card"><div class="metric-top">Awaiting response <span class="metric-icon">◷</span></div><div class="metric-value">${pending}</div><div class="metric-note">Follow up when ready</div></div><div class="metric-card"><div class="metric-top">Dietary notes <span class="metric-icon">♡</span></div><div class="metric-value">${state.guests.filter(x=>x.dietary&&x.dietary!=='None').length}</div><div class="metric-note">Guest-provided preferences</div></div></div><div class="card"><div class="card-header"><div><div class="card-title">Guest list</div><div class="card-subtitle">Contact details are stored in this browser’s demo workspace</div></div><input class="search-input" id="guestSearch" placeholder="Search guests…"></div><div class="table-wrap"><table class="table" id="guestTable"><thead><tr><th>Name</th><th>Contact</th><th>Group</th><th>RSVP</th><th>Dietary notes</th><th></th></tr></thead><tbody>${state.guests.map(g=>`<tr><td><strong>${esc(g.name)}</strong></td><td>${esc(g.contact||'—')}</td><td>${esc(g.category||'—')}</td><td><select class="guest-rsvp" data-rsvp="${g.id}" aria-label="${esc(g.name)} RSVP"><option ${g.rsvp==='Pending'?'selected':''}>Pending</option><option ${g.rsvp==='Yes'?'selected':''}>Yes</option><option ${g.rsvp==='No'?'selected':''}>No</option></select></td><td>${esc(g.dietary||'—')}</td><td><button class="small-action" data-delete-guest="${g.id}">Remove</button></td></tr>`).join('')||'<tr><td colspan="6">No guests yet. Add guests or import a CSV.</td></tr>'}</tbody></table></div></div>`}
function renderIdeas(){return `${heading('A spark of inspiration','Thoughtful ideas tailored to your garden wedding, Jaipur, and guest list.',button('Ask Genie for ideas','open-assistant','secondary-button','✧'))}<div class="idea-grid">${[['✿','A garden that glows','DECOR','Layer warm lanterns and soft fairy lights through the garden paths. Add seasonal florals at key gathering points to keep the look welcoming and focused.'],['♫','A relaxed dinner soundtrack','ENTERTAINMENT','Mix acoustic live music during dinner with a playlist you love for later. Confirm sound limits with your venue before booking.'],['❀','A menu with everyone in mind','CATERING','Build a vegetarian-forward menu with clearly marked Jain options, plus a few familiar favorites for guests of all ages.']].map(([icon,title,cat,desc],i)=>`<article class="idea-card"><div class="idea-art">${icon}</div><div class="idea-copy"><small>${cat} · PERSONALIZED IDEA</small><strong>${title}</strong><p>${desc}</p><button class="small-action" data-save-idea="${i}">${state.ideasSaved.includes(title)?'✓ Saved':'♡ Save idea'}</button></div></article>`).join('')}</div><div class="card section-gap"><div class="card-header"><div><div class="card-title">Your inspiration notes</div><div class="card-subtitle">Saved ideas stay in this browser</div></div></div>${state.ideasSaved.length?state.ideasSaved.map(x=>`<div class="vendor-row"><div class="vendor-logo">✧</div><div class="vendor-copy"><strong>${esc(x)}</strong><small>Saved for ${esc(state.event.name)}</small></div></div>`).join(''):'<div class="overview-meta">Save an idea above and it will appear here.</div>'}</div>`}
function inlineMarkdown(text){let s=esc(text);s=s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');s=s.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');return s}
function markdownHtml(text){let out=[],paragraph=[],list=[];const flushP=()=>{if(paragraph.length){out.push(`<p>${paragraph.map(inlineMarkdown).join('<br>')}</p>`);paragraph=[]}},flushL=()=>{if(list.length){out.push(`<ul>${list.map(x=>`<li>${inlineMarkdown(x)}</li>`).join('')}</ul>`);list=[]}},cells=line=>line.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(x=>x.trim()),isDivider=line=>/^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line);let lines=String(text||'').split(/\r?\n/);for(let i=0;i<lines.length;i++){let line=lines[i],h=/^(#{1,3})\s+(.+)$/.exec(line),li=/^\s*[-*]\s+(.+)$/.exec(line);if(line.includes('|')&&i+1<lines.length&&isDivider(lines[i+1])){flushP();flushL();let headers=cells(line);i++;let rows=[];while(i+1<lines.length&&lines[i+1].includes('|')&&lines[i+1].trim()){rows.push(cells(lines[++i]))}out.push(`<div class="chat-table-wrap"><table class="chat-md-table"><thead><tr>${headers.map(x=>`<th>${inlineMarkdown(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${headers.map((_,j)=>`<td>${inlineMarkdown(row[j]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}else if(!line.trim()){flushP();flushL()}else if(h){flushP();flushL();let n=h[1].length;out.push(`<h${n+2}>${inlineMarkdown(h[2])}</h${n+2}>`)}else if(li){flushP();list.push(li[1])}else{flushL();paragraph.push(line)}}flushP();flushL();return out.join('')}
function chatMessagesHtml(){let rows=chatHistory.map(m=>{let user=m.role==='user',action=m.action,actionHtml='';if(action){let status=action.status||'pending',pending=status==='pending'&&action.expiresAt>Date.now(),details=action.type==='portal_change'?esc(action.summary||action.proposal?.summary||'Update portal details'):action.type==='adjust_budget'?`${esc(action.currency||state.event.currency)}${Number(action.from).toLocaleString('en-IN')} → ${esc(action.currency||state.event.currency)}${Number(action.to).toLocaleString('en-IN')}`:`${Number(action.from).toLocaleString('en-IN')} → ${Number(action.to).toLocaleString('en-IN')} guests`;actionHtml=`<div class="chat-action-card"><strong>${action.type==='portal_change'?'Portal change proposal':action.type==='adjust_budget'?'Budget change proposal':'Guest count proposal'}</strong><span>${details}</span>${pending?`<div class="chat-action-buttons"><button class="primary-button" data-confirm-chat-action="${esc(action.id)}">Confirm change</button><button class="secondary-button" data-reject-chat-action="${esc(action.id)}">Keep current plan</button></div>`:`<small class="action-status">${status==='confirmed'?'Applied to your event':status==='rejected'?'Kept current plan':status==='conflict'?'Plan changed; ask again':'Proposal expired'}</small>`}</div>`}return `<article class="chat-message ${user?'from-user':''}"><div class="chat-message-avatar">${user?esc((apiUser?.name||'P')[0].toUpperCase()):'✳'}</div><div class="chat-message-body"><div class="chat-message-content">${markdownHtml(m.content)}</div>${actionHtml}${!user&&m.model?`<small class="chat-model">NVIDIA NIM · ${esc(m.model)}</small>`:''}</div></article>`}).join('');if(optimisticMessage)rows+=`<article class="chat-message from-user"><div class="chat-message-avatar">${esc((apiUser?.name||'P')[0].toUpperCase())}</div><div class="chat-message-body"><div class="chat-message-content">${markdownHtml(optimisticMessage)}</div>${chatBusy?'':'<small class="chat-model">Not sent · retry to send</small>'}</div></article>`;if(!rows)rows='<div class="chat-welcome"><div class="welcome-spark">✳</div><strong>Hi! What are you planning?</strong><p>Ask about your event, tasks, expenses, vendors, themes, guests, and next steps. Requested workspace changes appear here for your approval before they are applied.</p></div>';return rows+(chatBusy?'<div class="typing-row"><span class="typing-avatar">✳</span><div class="typing-indicator"><i></i><i></i><i></i><span>Genie is thinking</span></div></div>':'')}
function renderAssistant(){return `${heading('Your event sidekick','Ask questions or request changes across your event workspace. Confirm a proposal to apply it.',`<button class="secondary-button" data-action="clear-chat">⌫ Clear conversation</button>`)}<div class="assistant-layout"><div class="card chat-card"><div class="chat-thread" id="pageMessages">${chatMessagesHtml()}</div><div class="chat-error-area" id="pageChatError"></div><form class="chat-compose"><input class="chat-input" placeholder="Ask or make a change…" autocomplete="off" aria-label="Message EventGenie AI"><button class="primary-button">Send →</button></form></div><div class="card"><div class="card-title">Try asking</div><div class="card-subtitle">Ask questions or tell Genie what to update</div><button class="suggestion" data-prompt="What tasks are pending?">What tasks are pending?</button><button class="suggestion" data-prompt="Add a high priority task: confirm the caterer, due 2026-11-20">Add a task</button><button class="suggestion" data-prompt="Change my theme to traditional Indian wedding">Change my theme</button><button class="suggestion" data-prompt="Add an expense called Lighting for ₹25,000">Add an expense</button><button class="suggestion" data-prompt="Mark Saffron Table Co. as Booked">Update a vendor status</button><div class="alert-note">${cloudMode?'NVIDIA NIM uses your saved workspace. Supported updates are validated, then applied only after you confirm.':serverOnline?'Local demo chat uses live NVIDIA NIM. Changes update this browser after confirmation.':'Start the EventGenie backend to use NVIDIA AI chat.'}</div></div></div>`}
function renderReports(){return `${heading('Everything, ready to share','Export a CSV snapshot of your planning data.',button('↓ Export event report','export-report'))}<div class="page-columns"><div class="card"><div class="card-title">Your report includes</div><div class="tasks-list" style="margin-top:12px">${['Event overview and key details','Budget allocations and recorded expenses','Vendor shortlist and quotes','Preparation timeline and task statuses','Guest RSVP and dietary summary'].map(x=>`<div class="task-row"><span class="metric-icon">✓</span><div class="task-copy"><strong>${x}</strong><small>Included in the downloadable CSV report</small></div></div>`).join('')}</div><div class="alert-note">PDF export is not configured. The CSV report is generated from your current saved workspace.</div></div><div class="card"><div class="card-title">Data handling</div><p class="card-subtitle" style="line-height:1.7">${cloudMode?'The account workspace is saved on the EventGenie server and scoped to your signed-in account. Account data is not stored in browser local storage.':'This demo stores planning information in local browser storage only. It is not synced or protected by user accounts. Avoid entering sensitive information.'}</p></div></div>`}
async function apiRequest(url,options={}){let r=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}}),data={};try{data=await r.json()}catch{}if(!r.ok){let err=new Error(data.error||`Request failed (${r.status})`);err.status=r.status;throw err}return data}
function renderLanding(){let root=$('#landingRoot')||document.body.appendChild(Object.assign(document.createElement('div'),{id:'landingRoot'}));$('#authRoot')?.remove();root.innerHTML=`<div class="landing-page"><header class="landing-header"><a class="brand landing-brand" href="#landingTop" aria-label="EventGenie home"><span class="brand-mark">✳</span><span>eventgenie<span class="brand-ai">AI</span></span></a><nav class="landing-nav" aria-label="Landing page navigation"><a href="#services">Services</a><a href="#how-it-works">How it works</a><a href="#celebrations">Celebrations</a></nav><div class="landing-actions"><button class="landing-login" data-auth-action="login">Sign in</button><button class="primary-button" data-auth-action="register">Create account <span>→</span></button></div><button class="landing-menu" id="landingMenu" aria-label="Toggle navigation">☰</button></header><main id="landingTop"><section class="landing-hero"><div class="landing-hero-copy"><div class="landing-eyebrow"><span>✳</span> EVENT PLANNING, MADE PERSONAL</div><h1>Make room for the <em>moments.</em><br>We’ll help with the plan.</h1><p>From the first budget idea to the last dance, keep your event details, tasks, guests, and vendors together in one thoughtful workspace.</p><div class="landing-hero-actions"><button class="primary-button landing-cta" data-auth-action="register">Start planning for free <span>→</span></button><a class="landing-secondary" href="#services">Explore services <span>↓</span></a></div><div class="landing-assurance"><span>✓</span> Your plan, your choices. No vendor gets booked without you.</div></div><div class="landing-visual"><div class="visual-orbit orbit-one"></div><div class="visual-orbit orbit-two"></div><div class="visual-flower flower-one">✿</div><div class="visual-flower flower-two">✽</div><div class="visual-spark spark-one">✦</div><div class="planner-preview"><div class="preview-top"><span class="preview-dot"></span><span class="preview-dot"></span><span class="preview-dot"></span><small>YOUR EVENT WORKSPACE</small><span class="preview-avatar">✳</span></div><div class="preview-content"><div class="preview-label">A PLAN THAT FEELS LIKE YOU</div><h3>Your celebration,<br>all coming together.</h3><div class="preview-meta"><span>▦ Your event date</span><span>♧ Your guest list</span></div><div class="preview-divider"></div><div class="preview-row"><div class="preview-row-icon">◉</div><div><strong>Budget, in balance</strong><small>Planned and actual costs together</small></div><span class="preview-arrow">↗</span></div><div class="preview-row"><div class="preview-row-icon green">◷</div><div><strong>One clear next step</strong><small>Tasks arranged around your day</small></div><span class="preview-arrow">↗</span></div><div class="preview-foot"><span>✧</span> Your details stay yours to decide</div></div></div><div class="visual-note"><span>✦</span><div><strong>Thoughtful by design</strong><small>Every detail has a place</small></div></div></div></section><section class="landing-trustline"><span>MADE FOR THE DAYS THAT MATTER</span><div><span>Weddings</span><i>✳</i><span>Birthdays</span><i>✳</i><span>Community</span><i>✳</i><span>Work & campus</span></div></section><section class="landing-section" id="services"><div class="landing-section-heading"><div class="landing-eyebrow">YOUR EVENT TOOLKIT</div><h2>All the moving pieces,<br><em>in one calmer place.</em></h2><p>Practical planning tools that flex around your event, priorities, and budget.</p></div><div class="service-grid"><article class="service-card service-featured"><div class="service-icon lavender">✧</div><span class="service-kicker">PLAN WITH CONTEXT</span><h3>Your AI event companion</h3><p>Ask questions about your saved event, get ideas, compare your entered quotes, and review what’s next. Requested updates to your event, tasks, expenses, vendors, and guests are reviewed before saving.</p><div class="service-sample"><span>“What should I finish this week?”</span><b>Ask Genie ↗</b></div></article><article class="service-card"><div class="service-icon peach">◉</div><span class="service-kicker">MONEY, MADE CLEAR</span><h3>Budget that adds up</h3><p>Plan by category, record actual costs, track payments, and see what remains. Estimates stay distinct from amounts you’ve paid.</p><div class="service-mini-bars"><i></i><i></i><i></i><i></i><i></i></div></article><article class="service-card"><div class="service-icon sage">◷</div><span class="service-kicker">ONE STEP AT A TIME</span><h3>A timeline you can follow</h3><p>Keep deadlines and task status visible, mark progress, and know which planning steps need attention.</p><div class="service-mini-timeline"><i></i><i></i><i></i><span>Plan · Prepare · Celebrate</span></div></article><article class="service-card"><div class="service-icon sand">◇</div><span class="service-kicker">YOUR PEOPLE & PARTNERS</span><h3>Guests and vendors together</h3><p>Track RSVPs and dietary notes, organize vendor contacts and quotations, and keep booking decisions in your hands.</p><div class="service-tags"><span>RSVPs</span><span>Quotes</span><span>Notes</span></div></article><article class="service-card"><div class="service-icon rose">✿</div><span class="service-kicker">IDEAS TO MAKE IT YOURS</span><h3>Themes and inspiration</h3><p>Explore decoration, lighting, food, and activity ideas shaped around your event details and preferences.</p><div class="service-swatch"><i></i><i></i><i></i><i></i><span>YOUR STYLE</span></div></article><article class="service-card"><div class="service-icon blue">▤</div><span class="service-kicker">READY WHEN YOU ARE</span><h3>A report you can share</h3><p>Export your event overview, spending plan, vendor list, guest summary, and checklist as a CSV report.</p><div class="service-report"><span>EVENT PLAN</span><b>↓</b></div></article></div></section><section class="landing-how" id="how-it-works"><div class="landing-how-inner"><div class="landing-eyebrow">A SIMPLE PLACE TO BEGIN</div><h2>From “we should”<br>to <em>“we did.”</em></h2><div class="how-steps"><article><span>01</span><div class="how-icon">✧</div><h3>Tell us the essentials</h3><p>Share the date, place, guest count, budget, and the things that matter most.</p></article><article><span>02</span><div class="how-icon">◉</div><h3>Shape your plan</h3><p>Organize expenses, tasks, vendors, and guest details in your workspace.</p></article><article><span>03</span><div class="how-icon">✿</div><h3>Make it yours</h3><p>Review suggestions, adjust your plan, and choose what works for your event.</p></article></div></div></section><section class="landing-occasions" id="celebrations"><div><div class="landing-eyebrow">BIG DAY OR SMALL GATHERING</div><h2>Whatever brings you<br><em>together.</em></h2><p>Start with the event you have in mind. EventGenie gives you a flexible workspace to plan it your way.</p><button class="primary-button" data-auth-action="register">Create your workspace <span>→</span></button></div><div class="occasion-list"><div><span>01</span><strong>Weddings & anniversaries</strong><i>↗</i></div><div><span>02</span><strong>Birthdays & family celebrations</strong><i>↗</i></div><div><span>03</span><strong>College & community events</strong><i>↗</i></div><div><span>04</span><strong>Corporate & custom gatherings</strong><i>↗</i></div></div></section><section class="landing-final"><div class="final-spark">✳</div><div class="landing-eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h2>Let’s make a plan<br><em>for something lovely.</em></h2><p>Create your account and bring your event details into one place.</p><button class="primary-button landing-cta" data-auth-action="register">Create your account <span>→</span></button><button class="auth-link demo-from-landing" data-auth-action="demo">Or explore the local demo</button></section></main><footer class="landing-footer"><a class="brand" href="#landingTop"><span class="brand-mark">✳</span><span>eventgenie<span class="brand-ai">AI</span></span></a><span>Thoughtful plans for meaningful moments.</span><div><a href="#services">Services</a><button data-auth-action="login">Sign in</button></div><small>AI chat requires a configured NVIDIA NIM connection. Vendor information is user-entered and unverified.</small></footer></div>`;root.classList.add('landing-root')}
function renderAuth(){let root=$('#authRoot')||document.body.appendChild(Object.assign(document.createElement('div'),{id:'authRoot'}));$('#landingRoot')?.remove();let register=authTab==='register';root.innerHTML=`<div class="auth-screen"><section class="auth-card"><a class="brand" href="#" data-auth-action="back"><span class="brand-mark">✳</span><span>eventgenie<span class="brand-ai">AI</span></span></a><div class="eyebrow">${serverOnline?'YOUR PRIVATE WORKSPACE':'LOCAL DEMO'}</div><h1>${register?'Create your account':'Welcome back'}</h1><p>${register?'Create an account to save your event privately on this server.':'Sign in to load your event plan from this server.'}</p>${serverOnline?'':'<div class="auth-offline">The account server is unavailable. Start EventGenie’s backend to sign in, or continue in the local demo.</div>'}<form id="authForm">${register?`<div class="form-field"><label for="authName">Your name</label><input id="authName" name="name" autocomplete="name" minlength="2" maxlength="80" required></div>`:''}<div class="form-field"><label for="authEmail">Email address</label><input id="authEmail" name="email" type="email" autocomplete="email" maxlength="254" required></div><div class="form-field"><label for="authPassword">Password</label><input id="authPassword" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="12" maxlength="200" required></div><div class="auth-error" id="authError" role="alert"></div><button class="primary-button">${register?'Create account':'Sign in'}</button></form><div class="auth-links"><button class="auth-link" data-auth-action="switch">${register?'Already have an account? Sign in':'Create an account'}</button><button class="auth-link" data-auth-action="back">← Back to home</button></div><div class="auth-links"><button class="auth-link" data-auth-action="demo">Continue in local demo</button></div><div class="auth-footnote">Passwords must be at least 12 characters. The local demo stores its data only in this browser and does not provide account security.</div></section></div>`;$('#authForm').onsubmit=submitAuth}
async function submitAuth(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget)),err=$('#authError');err.classList.remove('show');try{let data=await apiRequest(authTab==='register'?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(d)});apiUser=data.user;state=data.workspace||(await apiRequest('/api/workspace')).workspace;cloudRevision=data.revision||1;cloudMode=true;authRequired=false;await loadChatHistory();updateAccountUi();render();notify(authTab==='register'?'Account created. Your workspace is saved on this server.':'Signed in. Your workspace is up to date.')}catch(x){err.textContent=x.message;err.classList.add('show')}}
async function loadChatHistory(){if(!cloudMode){chatHistory=[];chatConfig={configured:false,model:null};return}const results=await Promise.allSettled([apiRequest('/api/chat/history'),apiRequest('/api/chat/status')]);if(results[0].status==='fulfilled')chatHistory=results[0].value.messages||[];else chatHistory=[];if(results[1].status==='fulfilled')chatConfig=results[1].value;else chatConfig={configured:false,model:null}}
function loadDemoChat(){try{let rows=JSON.parse(localStorage.getItem(DEMO_CHAT_KEY))||[];chatHistory=Array.isArray(rows)?rows.filter(m=>['user','assistant'].includes(m?.role)&&typeof m.content==='string').slice(-80):[]}catch{chatHistory=[]}}
function saveDemoChat(){if(!cloudMode)localStorage.setItem(DEMO_CHAT_KEY,JSON.stringify(chatHistory.slice(-80)))}
function demoContext(){return{event:state.event,expenses:state.expenses.map(({name,category,planned,actual})=>({name,category,planned,actual})),tasks:state.tasks.map(({title,category,due,priority,status})=>({title,category,due,priority,status})),vendors:state.vendors.map(({name,category,quote,location,status,notes})=>({name,category,quote,location,status,notes})),guests:state.guests.map(({rsvp})=>({rsvp}))}}
function persistCloud(){cloudSaveQueue=cloudSaveQueue.catch(()=>{}).then(async()=>{if(!cloudMode)return;try{let result=await apiRequest('/api/workspace',{method:'PUT',headers:{'If-Match':String(cloudRevision)},body:JSON.stringify(state)});cloudRevision=result.revision}catch(err){if(err.status===401){cloudMode=false;apiUser=null;state=structuredClone(initial);authRequired=true;authPage='landing';render();return}if(err.status===409){notify('This workspace changed in another session. Sign in again to load the latest saved version before editing further.');return}notify(`Server save failed: ${err.message}`)}});return cloudSaveQueue}
let serverOnline=false;
async function bootBackend(){try{await apiRequest('/api/health');serverOnline=true;try{let me=await apiRequest('/api/auth/me');apiUser=me.user;let w=await apiRequest('/api/workspace');state=w.workspace;cloudRevision=w.revision;cloudMode=true;await loadChatHistory()}catch(err){if(err.status===401){authRequired=true;authPage='landing';state=structuredClone(initial)}else throw err}}catch{serverOnline=false;authRequired=true;authPage='landing';cloudMode=false}updateAccountUi();render()}
function updateAccountUi(){let badge=$('#storageBadge');if(badge){badge.lastChild.textContent=cloudMode?' Server saved':' Local demo';badge.title=cloudMode?'Changes sync to your EventGenie server':'Changes are saved in this browser only'}let n=apiUser?.name||'Priya Sharma';let p=$('.profile-copy strong');if(p)p.textContent=n;let small=$('.profile-copy small');if(small)small.textContent=cloudMode?'Account workspace':'Local demo';let av=(n.trim()[0]||'P').toUpperCase();if($('#topAvatar'))$('#topAvatar').textContent=av;let sidebarAvatar=$('.profile .avatar');if(sidebarAvatar)sidebarAvatar.textContent=av}
function renderSettings(){return `${heading('Your workspace settings','Manage your account, preferences, and local data.','')}<div class="page-columns"><div class="card"><div class="card-title">${cloudMode?'Account':'Demo workspace'}</div><p class="card-subtitle" style="line-height:1.7;margin:10px 0 17px">${cloudMode?`Signed in as ${esc(apiUser.name)} (${esc(apiUser.email)}). Your account workspace is stored on this server, not in browser storage.`:'You are using local demo mode. Event details are stored in this browser only.'}</p>${cloudMode?'<button class="secondary-button" data-action="logout">Sign out</button>':''}<div class="form-field" style="margin-top:17px"><label for="prefCurrency">Default event currency</label><select id="prefCurrency"><option ${state.event.currency==='₹'?'selected':''}>₹</option><option ${state.event.currency==='$'?'selected':''}>$</option><option ${state.event.currency==='€'?'selected':''}>€</option><option ${state.event.currency==='£'?'selected':''}>£</option></select></div><div class="form-actions" style="justify-content:flex-start"><button class="primary-button" data-action="save-settings">Save preference</button></div></div><div class="card"><div class="card-title">${cloudMode?'Server workspace':'Local demo data'}</div><p class="card-subtitle" style="line-height:1.7;margin:10px 0 17px">${cloudMode?'Resetting replaces your saved server workspace with the starter event.':'Clearing the demo removes the saved event, guests, vendors, and tasks from this browser.'}</p><button class="secondary-button" data-action="reset-demo">${cloudMode?'Reset server workspace':'Reset demo workspace'}</button></div></div>`}
function render(){let c=$('#pageContent');if(authRequired){if(authPage==='landing')renderLanding();else renderAuth();return}else{$('#authRoot')?.remove();$('#landingRoot')?.remove()}c.innerHTML=({home:renderHome,budget:renderBudget,timeline:renderTimeline,vendors:renderVendors,guests:renderGuests,ideas:renderIdeas,assistant:renderAssistant,reports:renderReports,settings:renderSettings}[view]||renderHome)();bindView();updateAccountUi()}
function showModal(title,sub,fields,onSave){let root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><h2 id="modalTitle">${title}</h2><p>${sub}</p></div><button class="icon-button" data-close-modal aria-label="Close">✕</button></div><form class="modal-body" id="modalForm"><div class="form-grid">${fields}</div><div class="form-actions"><button type="button" class="secondary-button" data-close-modal>Cancel</button><button class="primary-button">Save changes</button></div></form></section></div>`;root.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};root.querySelector('form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget));if(onSave(d)===false)return;root.innerHTML='';save();render()};root.querySelector('input,select,textarea')?.focus()}
const field=(label,name,value='',type='text',opts='')=>`<div class="form-field"><label for="f-${name}">${label}</label>${type==='select'?`<select id="f-${name}" name="${name}" required>${opts}</select>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0"':''} required>`}</div>`,sel=(items,current)=>items.map(x=>`<option ${x===current?'selected':''}>${x}</option>`).join('');
function eventModal(){let e=state.event;showModal('Plan something wonderful','Tell Genie a little about the event you’re planning.',`${field('Event name','name',e.name)}${field('Event type','type',e.type,'select',sel(['Wedding','Birthday','Anniversary','Baby shower','College festival','Community gathering','Corporate event','Custom event'],e.type))}${field('Event date','date',e.date,'date')}${field('Event time (optional)','time',e.time||'','time')}${field('Location','location',e.location)}${field('Estimated guests','guests',e.guests,'number')}${field('Total budget','budget',e.budget,'number')}${field('Currency','currency',e.currency)}${field('Theme','theme',e.theme)}${field('Venue type','venue',e.venue)}${field('Venue tier','venueTier',e.venueTier||'')}${field('Dietary requirements','dietary',e.dietary)}${field('Catering notes','cateringNotes',e.cateringNotes||'')}<div class="form-field full"><label for="f-priorities">Priorities and accessibility needs</label><textarea id="f-priorities" name="priorities">${esc(e.priorities||'')}</textarea></div>`,d=>{let budget=+d.budget,guests=+d.guests;if(!d.date||d.date<new Date().toISOString().slice(0,10)){notify('Choose today or a future event date.');return false}if(!Number.isFinite(budget)||budget<=0||!Number.isInteger(guests)||guests<1){notify('Budget and guest count must be greater than zero.');return false}if(state.tasks.some(t=>t.due>d.date)){notify('Some tasks are scheduled after that event date. Update their deadlines before saving this date.');return false}let oldBudget=+state.event.budget,planned=totals().planned;Object.assign(state.event,d,{guests,budget});if(oldBudget>0&&planned>0&&budget!==oldBudget)scaleAllocations(budget);else if(planned===0)allocateToBudget(budget);notify('Your event details are saved.')})}
function allocateToBudget(budget){const weights=[.25,.25,.15,.1,.075,.0375,.075,.0625];state.expenses.forEach((x,i)=>x.planned=Math.round(budget*weights[i]));let diff=budget-totals().planned;if(state.expenses.length)state.expenses[state.expenses.length-1].planned+=diff}
function scaleAllocations(n){let old=totals().planned;if(old<=0){allocateToBudget(n);return}let sum=0;state.expenses.forEach((x,i)=>{x.planned=i===state.expenses.length-1?0:Math.round((+x.planned/old)*n);sum+=x.planned});if(state.expenses.length)state.expenses.at(-1).planned=n-sum}
function expenseModal(item){let x=item||{name:'',category:'Venue',planned:'',actual:0};showModal(item?'Edit expense':'Add an expense','Track planned estimates and payments you have actually made.',`${field('Expense name','name',x.name)}${field('Category','category',x.category,'select',sel(['Venue','Catering','Decoration','Photography','Entertainment','Transportation','Invitations','Clothing','Accommodation','Miscellaneous'],x.category))}${field('Planned amount','planned',x.planned,'number')}${field('Actual paid','actual',x.actual,'number')}`,d=>{if(item)Object.assign(item,d,{planned:+d.planned,actual:+d.actual});else state.expenses.push({id:Date.now(),...d,planned:+d.planned,actual:+d.actual});notify('Expense saved.')})}
function taskModal(){showModal('Add a planning task','Give your next step a clear owner and due date.',`${field('Task title','title')}${field('Category','category','Planning','select',sel(['Planning','Venue','Vendor','Guests','Catering','Decoration','Travel','Other'],'Planning'))}${field('Due date','due',state.event.date,'date')}${field('Priority','priority','Medium','select',sel(['High','Medium','Low'],'Medium'))}${field('Assigned person','assigned','Priya')}${field('Status','status','Not started','select',sel(['Not started','In progress','Completed','Blocked'],'Not started'))}`,d=>{if(d.due>state.event.date){notify('Task date is after the event date; please choose an earlier date.');return}state.tasks.push({id:Date.now(),...d});notify('Task added to your timeline.')})}
function vendorModal(){showModal('Add a vendor','Save details and quotations supplied by you.',`${field('Business name','name')}${field('Service category','category','Venue','select',sel(['Venue','Catering','Photographer','Decorator','Florist','DJ','Entertainment','Transportation','Accommodation','Other'],'Venue'))}${field('Contact details','contact')}${field('Location','location',state.event.location)}${field('Quoted price','quote','0','number')}${field('Booking status','status','Shortlisted','select',sel(['Shortlisted','Contacted','Quote received','Booked','Declined'],'Shortlisted'))}<div class="form-field full"><label for="f-notes">Notes / terms</label><textarea name="notes" id="f-notes"></textarea></div>`,d=>{state.vendors.push({id:Date.now(),...d,quote:+d.quote});notify('Vendor added. Booking status reflects your entry.')})}
function guestModal(){showModal('Add a guest','Guest contact details are saved privately in this browser demo.',`${field('Guest name','name')}${field('Email or phone','contact')}${field('Guest group','category','Friends')}${field('RSVP','rsvp','Pending','select',sel(['Pending','Yes','No'],'Pending'))}${field('Dietary notes','dietary','None')}`,d=>{state.guests.push({id:Date.now(),...d});notify('Guest added to your list.')})}
function optimizer(){let before=state.event.budget;showModal('Adjust your budget','Choose a new total. We’ll scale current allocations proportionally, then you can review each line before accepting.',`${field('Current budget','old',before,'number')}${field('New budget','budget',before,'number')}`,d=>{let n=+d.budget;if(!Number.isFinite(n)||n<=0){notify('Enter a budget greater than zero.');return false}scaleAllocations(n);state.event.budget=n;notify('Allocations scaled proportionally. Review and edit any line item.')})}
function download(name,content,type='text/csv'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function csv(rows){return rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}function exportGuests(){download('eventgenie-guests.csv',csv([['Name','Contact','Group','RSVP','Dietary'],...state.guests.map(x=>[x.name,x.contact,x.category,x.rsvp,x.dietary])]))}function exportReport(){let rows=[['EVENTGENIE EVENT REPORT'],['Event',state.event.name],['Type',state.event.type],['Date',state.event.date],['Location',state.event.location],['Guests',state.event.guests],['Budget',state.event.currency+state.event.budget],[],['EXPENSES'],['Name','Category','Planned','Actual'],...state.expenses.map(x=>[x.name,x.category,x.planned,x.actual]),[],['TASKS'],['Task','Category','Due','Priority','Status'],...state.tasks.map(x=>[x.title,x.category,x.due,x.priority,x.status]),[],['VENDORS'],['Business','Service','Contact','Quote','Status'],...state.vendors.map(x=>[x.name,x.category,x.contact,x.quote,x.status]),[],['GUESTS'],['Name','Contact','Group','RSVP','Dietary'],...state.guests.map(x=>[x.name,x.contact,x.category,x.rsvp,x.dietary])];download('eventgenie-event-report.csv',csv(rows));notify('Your event report is ready.')}
function showChatError(message){lastFailedMessage=message?.startsWith('Sign in')?'':lastFailedMessage;const errorHtml=`<div class="chat-error"><span>${esc(message)}</span>${lastFailedMessage?'<button data-retry-chat>Retry</button>':''}</div>`;for(const id of ['pageChatError','widgetChatError']){let el=$(`#${id}`);if(el)el.innerHTML=errorHtml}}
function renderChatSurfaces(){for(const id of ['pageMessages','widgetMessages']){let el=$(`#${id}`);if(el){el.innerHTML=chatMessagesHtml();el.scrollTop=el.scrollHeight}}let status=$('#chatWidgetStatus');if(status)status.textContent=cloudMode?(chatConfig.configured?`NVIDIA NIM · ${chatConfig.model}`:'Server ready · NVIDIA key required'):serverOnline?'NVIDIA NIM · local demo':'Start backend for NVIDIA chat';$$('.chat-compose button').forEach(b=>b.disabled=chatBusy);$$('.chat-input').forEach(i=>i.disabled=chatBusy)}
async function chatSend(text){text=String(text||'').trim();if(!text||chatBusy)return;if(!serverOnline){lastFailedMessage=text;showChatError('The EventGenie backend is unavailable. Start it with Run-EventGenie.bat to use live NVIDIA AI chat.');return}lastFailedMessage=text;optimisticMessage=text;chatBusy=true;for(const id of ['pageChatError','widgetChatError'])if($(`#${id}`))$(`#${id}`).innerHTML='';renderChatSurfaces();try{if(cloudMode){const data=await apiRequest('/api/chat',{method:'POST',body:JSON.stringify({message:text})});chatHistory=data.messages||[]}else{const data=await apiRequest('/api/demo/chat',{method:'POST',body:JSON.stringify({message:text,context:demoContext(),history:chatHistory.slice(-20).map(({role,content})=>({role,content}))})});chatHistory.push({role:'user',content:text});chatHistory.push({role:'assistant',content:data.reply,model:data.model,action:data.action||null});chatHistory=chatHistory.slice(-80);saveDemoChat()}lastFailedMessage='';optimisticMessage='';chatBusy=false;renderChatSurfaces();$$('.chat-input').forEach(i=>i.value='')}catch(err){chatBusy=false;renderChatSurfaces();showChatError(err.message)}}
async function clearChat(){if(cloudMode){try{await apiRequest('/api/chat/history',{method:'DELETE'})}catch(err){showChatError(err.message);return}}chatHistory=[];if(!cloudMode)localStorage.removeItem(DEMO_CHAT_KEY);lastFailedMessage='';optimisticMessage='';for(const id of ['pageChatError','widgetChatError'])if($(`#${id}`))$(`#${id}`).innerHTML='';renderChatSurfaces()}
function applyDemoPortalChange(p){if(!p||p.type!=='portal_change'||!p.fields)throw Error('This change is not supported in the demo.');let f=p.fields;if(p.entity==='event'&&p.operation==='create'){state.event={...f};state.tasks=[];state.expenses=[];state.vendors=[];state.guests=[];state.ideasSaved=[];return}if(p.entity==='event'&&p.operation==='update'){if('date'in f&&state.tasks.some(t=>t.due>f.date))throw Error('Update task deadlines before moving the event to this date.');if('budget'in f){scaleAllocations(f.budget);state.event.budget=f.budget}Object.assign(state.event,f);return}let items=p.entity==='task'?state.tasks:p.entity==='expense'?state.expenses:p.entity==='vendor'?state.vendors:p.entity==='guest'?state.guests:null;if(!items)throw Error('This change is not supported in the demo.');if(p.operation==='create'){if(p.entity==='task'&&(!f.title||f.due>state.event.date))throw Error('The task details are no longer valid for this event date.');if(p.entity==='expense'&&(!f.name||!Number.isFinite(+f.planned)||+f.planned<0))throw Error('The expense details are invalid.');if((p.entity==='vendor'||p.entity==='guest')&&!f.name)throw Error('A name is required for this entry.');items.push({id:Date.now(),...f});return}let key=p.entity==='task'?'title':'name',matches=items.filter(x=>String(x[key]).toLowerCase()===String(p.target).toLowerCase());if(matches.length!==1)throw Error('The item changed or cannot be matched uniquely. Ask Genie again.');if(p.operation==='delete'){items.splice(items.indexOf(matches[0]),1);return}if(p.entity==='task'&&f.due>state.event.date)throw Error('Task deadline cannot be after the event date.');Object.assign(matches[0],f)}
async function decideChatAction(id,decision){if(!cloudMode){let message=chatHistory.find(m=>m.role==='assistant'&&m.action?.id===id);if(!message||message.action.status!=='pending'||message.action.expiresAt<=Date.now()){showChatError('This demo proposal expired. Ask Genie to prepare a fresh one.');return}if(decision==='confirm'){try{if(message.action.type==='portal_change')applyDemoPortalChange(message.action.proposal);else if(message.action.type==='adjust_budget'){scaleAllocations(message.action.to);state.event.budget=message.action.to}else if(message.action.type==='adjust_guests'){state.event.guests=message.action.to}else return showChatError('This demo action is not supported.')}catch(err){showChatError(err.message);return}save()}message.action.status=decision==='confirm'?'confirmed':'rejected';saveDemoChat();render();renderChatSurfaces();notify(decision==='confirm'?'Change applied to your local demo.':'Your local demo plan was left unchanged.');return}try{const data=await apiRequest(`/api/chat/actions/${encodeURIComponent(id)}`,{method:'POST',body:JSON.stringify({decision})});if(data.workspace){state=data.workspace;cloudRevision=data.revision;render()}const history=await apiRequest('/api/chat/history');chatHistory=history.messages;renderChatSurfaces();notify(decision==='confirm'?'Change applied to your saved event.':'Your saved plan was left unchanged.')}catch(err){showChatError(err.message);if(err.status===409){try{const fresh=await apiRequest('/api/workspace');state=fresh.workspace;cloudRevision=fresh.revision;render()}catch{}}}}
function bindView(){ $$('.chat-compose').forEach(form=>form.onsubmit=e=>{e.preventDefault();chatSend($('.chat-input',form).value)});$$('[data-prompt]').forEach(b=>b.onclick=()=>chatSend(b.dataset.prompt));$('#guestSearch')?.addEventListener('input',e=>filterTable('#guestTable',e.target.value));$('#vendorSearch')?.addEventListener('input',e=>filterTable('#vendorTable',e.target.value));$('#guestImport')?.addEventListener('change',importGuests);$$('[data-rsvp]').forEach(s=>s.onchange=()=>{let x=state.guests.find(g=>g.id==s.dataset.rsvp);x.rsvp=s.value;save();notify('RSVP updated.')})}
function filterTable(id,q){$$("tbody tr",$(id)).forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q.toLowerCase()))}
function importGuests(e){let f=e.target.files[0];if(!f)return;let reader=new FileReader();reader.onload=()=>{let lines=String(reader.result).split(/\r?\n/).filter(Boolean),parse=line=>{let a=[],cur='',quoted=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'&&line[i+1]==='"'&&quoted){cur+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){a.push(cur);cur=''}else cur+=c}a.push(cur);return a};let data=lines.slice(1).map(parse);data.forEach(row=>{if(row[0])state.guests.push({id:Date.now()+Math.random(),name:row[0],contact:row[1]||'',category:row[2]||'Other',rsvp:['Yes','No'].includes(row[3])?row[3]:'Pending',dietary:row[4]||'None'})});save();render();notify(`${data.filter(x=>x[0]).length} guests imported.`)};reader.readAsText(f)}
async function logout(){try{await apiRequest('/api/auth/logout',{method:'POST'});}catch{}cloudMode=false;apiUser=null;state=structuredClone(initial);authRequired=true;authPage='landing';render()}
function onAction(a){if(a==='new-event'||a==='edit-event')return eventModal();if(a==='add-expense')return expenseModal();if(a==='add-task')return taskModal();if(a==='add-vendor')return vendorModal();if(a==='add-guest')return guestModal();if(a==='optimizer')return optimizer();if(a==='export-guests')return exportGuests();if(a==='export-report')return exportReport();if(a==='open-assistant')return setView('assistant');if(a==='clear-chat')return clearChat();if(a==='logout')return logout();if(a==='save-settings'){state.event.currency=$('#prefCurrency').value;save();render();return notify('Currency preference saved.')}if(a==='reset-demo'){if(confirm('Clear your saved event and restore the starter workspace?')){state=structuredClone(initial);save();setView('home');notify('Workspace restored.')}return}}
document.addEventListener('click',e=>{if(e.target.closest('#chatFab')){let w=$('#chatWidget'),open=w.hidden;w.hidden=!open;$('#chatFab').setAttribute('aria-expanded',String(open));if(open){renderChatSurfaces();$('.chat-input',w)?.focus()}return}if(e.target.closest('#closeChatBtn')){$('#chatWidget').hidden=true;$('#chatFab').setAttribute('aria-expanded','false');return}if(e.target.closest('#clearChatBtn')){clearChat();return}let confirmAction=e.target.closest('[data-confirm-chat-action]');if(confirmAction){decideChatAction(confirmAction.dataset.confirmChatAction,'confirm');return}let rejectAction=e.target.closest('[data-reject-chat-action]');if(rejectAction){decideChatAction(rejectAction.dataset.rejectChatAction,'reject');return}if(e.target.closest('[data-retry-chat]')){chatSend(lastFailedMessage);return}if(e.target.closest('#landingMenu')){$('.landing-nav')?.classList.toggle('open');return}let auth=e.target.closest('[data-auth-action]');if(auth){let action=auth.dataset.authAction;if(action==='switch'){authTab=authTab==='login'?'register':'login';authPage='form';renderAuth()}else if(action==='login'||action==='register'){authTab=action;authPage='form';renderAuth()}else if(action==='back'){authPage='landing';render()}else if(action==='demo'){authRequired=false;authPage='landing';cloudMode=false;apiUser=null;try{state=JSON.parse(localStorage.getItem(STORE_KEY))||structuredClone(initial)}catch{state=structuredClone(initial)}loadDemoChat();render();notify(serverOnline?'Local demo ready. Genie uses live NVIDIA AI.':'Local demo ready. Start the backend to use NVIDIA AI chat.')}return}let nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return}let act=e.target.closest('[data-action]');if(act){onAction(act.dataset.action);return}let task=e.target.closest('[data-toggle-task]');if(task){let x=state.tasks.find(t=>t.id==task.dataset.toggleTask);x.status=x.status==='Completed'?'Not started':'Completed';save();render();return}let edit=e.target.closest('[data-edit-expense]');if(edit){expenseModal(state.expenses.find(x=>x.id==edit.dataset.editExpense));return}let del=e.target.closest('[data-delete-expense]');if(del){state.expenses=state.expenses.filter(x=>x.id!=del.dataset.deleteExpense);save();render();notify('Expense removed.');return}let dv=e.target.closest('[data-delete-vendor]');if(dv){state.vendors=state.vendors.filter(x=>x.id!=dv.dataset.deleteVendor);save();render();notify('Vendor removed.');return}let dg=e.target.closest('[data-delete-guest]');if(dg){state.guests=state.guests.filter(x=>x.id!=dg.dataset.deleteGuest);save();render();notify('Guest removed.');return}let idea=e.target.closest('[data-save-idea]');if(idea){let names=['A garden that glows','A relaxed dinner soundtrack','A menu with everyone in mind'],n=names[+idea.dataset.saveIdea];state.ideasSaved.includes(n)?state.ideasSaved=state.ideasSaved.filter(x=>x!==n):state.ideasSaved.push(n);save();render();notify(state.ideasSaved.includes(n)?'Idea saved.':'Idea removed from saved ideas.');return}if(e.target.closest('#profileBtn')){setView('settings');return}if(e.target.closest('#notificationsBtn'))notify(`${state.tasks.filter(x=>x.status!=='Completed'&&x.due<'2026-11-07').length} open task(s) are due this week.`);if(e.target.closest('#menuBtn'))$('#sidebar').classList.toggle('open')});
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));bootBackend();
